import { object, string, optional, array, any, enums, number } from '../../../runtime/validation/index.js';
import { contract } from '../../../runtime/Contracts.js';

/**
 * Mindmap module — EventBus contracts.
 *
 * All events carry `mapId` so subscribers can scope to the active map.
 * Payloads follow the NodeObj shape (see plan.md §NodeObj).
 */

const STATUS_ENUM = enums(['pending', 'in_progress', 'done', 'blocked', 'abandoned', 'failed']);
const SCHEMA_TYPE_ENUM = enums(['mindmap/branch', 'mindmap/leaf']);

export const MindmapContracts = {
  MINDMAP_NODE_ADDED: contract({
    version: 1,
    type: 'event',
    owner: 'mindmap',
    lifecycle: 'active',
    stability: 'stable',
    compliance: 'public',
    description: 'Published when a node (branch or leaf) is added to a map'
  }, object({
    mapId: string(),
    nodeId: string(),
    parentId: optional(string()),
    node: object({
      id: string(),
      topic: string(),
      schemaType: SCHEMA_TYPE_ENUM,
      status: STATUS_ENUM
    })
  })),

  MINDMAP_NODE_REMOVED: contract({
    version: 1,
    type: 'event',
    owner: 'mindmap',
    lifecycle: 'active',
    stability: 'stable',
    compliance: 'public',
    description: 'Published when a node is removed. cascaded lists child ids also removed.'
  }, object({
    mapId: string(),
    nodeId: string(),
    cascaded: array(string())
  })),

  MINDMAP_NODE_UPDATED: contract({
    version: 1,
    type: 'event',
    owner: 'mindmap',
    lifecycle: 'active',
    stability: 'stable',
    compliance: 'public',
    description: 'Published when node properties change (topic, status, metadata, ...)'
  }, object({
    mapId: string(),
    nodeId: string(),
    changes: object(),
    previousStatus: optional(string())
  })),

  MINDMAP_STRUCTURE_CHANGED: contract({
    version: 1,
    type: 'event',
    owner: 'mindmap',
    lifecycle: 'active',
    stability: 'stable',
    compliance: 'public',
    description: 'Published when the tree structure changes (collapse, expand, reorder within parent). moveNode publishes MINDMAP_NODE_MOVED instead.'
  }, object({
    mapId: string(),
    nodeId: string(),
    operation: enums(['collapse', 'expand', 'reorder']),
    details: optional(object())
  })),

  MINDMAP_NODE_MOVED: contract({
    version: 1,
    type: 'event',
    owner: 'mindmap',
    lifecycle: 'active',
    stability: 'stable',
    compliance: 'public',
    description: 'Published when a node is reparented'
  }, object({
    mapId: string(),
    nodeId: string(),
    fromParent: string(),
    toParent: string(),
    index: optional(number())
  })),

  MINDMAP_COLLAPSED: contract({
    version: 1,
    type: 'event',
    owner: 'mindmap',
    lifecycle: 'active',
    stability: 'stable',
    compliance: 'public',
    description: 'Published when a branch is collapsed or expanded (also fires MINDMAP_STRUCTURE_CHANGED with operation=collapse|expand; this event is the narrow semantic signal for chrome UIs).'
  }, object({
    mapId: string(),
    nodeId: string(),
    collapsed: any()
  })),

  MINDMAP_MAP_CREATED: contract({
    version: 1,
    type: 'event',
    owner: 'mindmap',
    lifecycle: 'active',
    stability: 'stable',
    compliance: 'public',
    description: 'Published when a new map is created'
  }, object({
    mapId: string(),
    name: string()
  })),

  MINDMAP_MAP_DELETED: contract({
    version: 1,
    type: 'event',
    owner: 'mindmap',
    lifecycle: 'active',
    stability: 'stable',
    compliance: 'public',
    description: 'Published when a map is deleted'
  }, object({
    mapId: string()
  }))
};

/**
 * MindmapStore — IDB-backed persistence for the mindmap module.
 *
 * Two logical stores over the CSMA storage module:
 *   - 'maps'      mapId  → { id, name, rootId, createdAt, updatedAt }
 *   - 'map_nodes' nodeId → NodeObj
 *
 * v1 is single-user local-first. Each map's nodes form a tree rooted at
 * one record; children live as separate records (one per NodeObj) so
 * search/filter can hit a subset. The whole tree is reconstructed at
 * loadMap() time by walking from the root.
 *
 * If the storage module is unavailable (e.g. test env without IDB), the
 * store degrades to an in-memory Map per logical store — so the service
 * is fully functional in tests.
 */

const DEFAULT_MAPS_STORE = 'mindmap_maps';
const DEFAULT_NODES_STORE = 'mindmap_map_nodes';

export class MindmapStore {
  constructor({ storage = null, mapsStore = DEFAULT_MAPS_STORE, nodesStore = DEFAULT_NODES_STORE } = {}) {
    this.storage = storage;
    this.mapsStore = mapsStore;
    this.nodesStore = nodesStore;
    this._memoryMaps = new Map();
    this._memoryNodes = new Map();
    this._ready = null;
  }

  /**
   * Ensure the storage backend is initialised and the required object
   * stores exist. Safe to call multiple times.
   */
  async init() {
    if (this._ready) return this._ready;
    this._ready = (async () => {
      if (!this.storage) return;
      if (typeof this.storage.init === 'function') {
        try {
          await this.storage.init({
            [this.mapsStore]: { keyPath: 'id', autoIncrement: false },
            [this.nodesStore]: { keyPath: 'id', autoIncrement: false }
          });
        } catch (err) {
          // Storage may already be initialised with a different schema;
          // fall through and try operations individually.
          this.storage = null;
        }
      }
    })();
    return this._ready;
  }

  // ─── Maps ────────────────────────────────────────────────────────

  async putMap(map) {
    await this.init();
    if (this.storage && typeof this.storage.update === 'function') {
      try { await this.storage.update(this.mapsStore, map); return; } catch { /* fall through */ }
    }
    this._memoryMaps.set(map.id, map);
  }

  async getMap(mapId) {
    await this.init();
    if (this.storage && typeof this.storage.get === 'function') {
      try { return await this.storage.get(this.mapsStore, mapId); } catch { /* fall through */ }
    }
    return this._memoryMaps.get(mapId) || null;
  }

  async listMaps() {
    await this.init();
    if (this.storage && typeof this.storage.getAll === 'function') {
      try {
        const all = await this.storage.getAll(this.mapsStore);
        if (Array.isArray(all)) return all;
      } catch { /* fall through */ }
    }
    return Array.from(this._memoryMaps.values());
  }

  async deleteMap(mapId) {
    await this.init();
    if (this.storage && typeof this.storage.delete === 'function') {
      try { await this.storage.delete(this.mapsStore, mapId); } catch { /* fall through */ }
    }
    this._memoryMaps.delete(mapId);
  }

  // ─── Nodes ───────────────────────────────────────────────────────

  async putNode(node) {
    await this.init();
    if (this.storage && typeof this.storage.update === 'function') {
      try { await this.storage.update(this.nodesStore, node); return; } catch { /* fall through */ }
    }
    this._memoryNodes.set(node.id, node);
  }

  async getNode(nodeId) {
    await this.init();
    if (this.storage && typeof this.storage.get === 'function') {
      try { return await this.storage.get(this.nodesStore, nodeId); } catch { /* fall through */ }
    }
    return this._memoryNodes.get(nodeId) || null;
  }

  async getAllNodes() {
    await this.init();
    if (this.storage && typeof this.storage.getAll === 'function') {
      try {
        const all = await this.storage.getAll(this.nodesStore);
        if (Array.isArray(all)) return all;
      } catch { /* fall through */ }
    }
    return Array.from(this._memoryNodes.values());
  }

  async deleteNode(nodeId) {
    await this.init();
    if (this.storage && typeof this.storage.delete === 'function') {
      try { await this.storage.delete(this.nodesStore, nodeId); } catch { /* fall through */ }
    }
    this._memoryNodes.delete(nodeId);
  }

  /**
   * Bulk delete (used for cascade removals).
   */
  async deleteNodes(nodeIds) {
    await Promise.all((nodeIds || []).map((id) => this.deleteNode(id)));
  }

  /**
   * Wipe all nodes for a map. Used by deleteMap so we don't leave
   * orphaned records behind.
   */
  async deleteNodesForMap(mapId) {
    const all = await this.getAllNodes();
    const ids = all.filter((n) => n.mapId === mapId).map((n) => n.id);
    await this.deleteNodes(ids);
  }
}

