  // ─── Layout convenience (renderers call this) ────────────────────

  layout(mapId, options = {}) {
    const map = this._getMap(mapId) || this._getMap(this._activeMapId);
    if (!map) return { nodes: [], links: [], bounds: { x: 0, y: 0, w: 0, h: 0 } };
