import { describe, it, expect } from 'vitest';
import { layout, DIRECTION, SIDE_LEFT, SIDE_RIGHT } from '../../src/modules/mindmap/services/LayoutEngine.js';

function leaf(id, topic, status = 'pending') {
  return { id, topic, schemaType: 'mindmap/leaf', status, children: [] };
}
function branch(id, topic, children = [], direction = undefined, status = 'pending') {
  return { id, topic, schemaType: 'mindmap/branch', status, children, expanded: true, direction };
}

describe('LayoutEngine', () => {
  it('rejects a missing root', () => {
    expect(() => layout(null)).toThrowError(/root/);
  });

  it('places a single root at origin', () => {
    const root = branch('r', 'root', []);
    const { nodes, links, bounds } = layout(root);
    expect(nodes).toHaveLength(1);
    expect(nodes[0].id).toBe('r');
    expect(nodes[0].x).toBe(0);
    expect(nodes[0].y).toBe(0);
    expect(links).toHaveLength(0);
    expect(bounds.w).toBeGreaterThan(0);
  });

  it('places three branches with SIDE direction and balances left/right', () => {
    const root = branch('r', 'root', [
      branch('a', 'A'),
      branch('b', 'B'),
      branch('c', 'C')
    ]);
    const { nodes, links } = layout(root);
    // root + 3 branches
    expect(nodes).toHaveLength(4);
    expect(links).toHaveLength(3);
    expect(links.every((l) => l.kind === 'main')).toBe(true);
    // Two children go right, one goes left (balance: first child LEFT when counts equal)
    const dirs = nodes.filter((n) => n.id !== 'r').map((n) => n.direction).sort();
    expect(dirs).toEqual([SIDE_LEFT, SIDE_RIGHT, SIDE_RIGHT]);
  });

  it('produces non-overlapping rectangles for sibling branches', () => {
    const root = branch('r', 'root', [
      branch('a', 'A', [leaf('a1', 'a1'), leaf('a2', 'a2'), leaf('a3', 'a3')]),
      branch('b', 'B', [leaf('b1', 'b1'), leaf('b2', 'b2')])
    ]);
    const { nodes } = layout(root);
    // Verify no two branch+leaf rectangles on the same side overlap vertically.
    const right = nodes.filter((n) => n.direction === SIDE_RIGHT);
    right.sort((a, b) => a.y - b.y);
    for (let i = 1; i < right.length; i += 1) {
      expect(right[i].y).toBeGreaterThanOrEqual(right[i - 1].y + right[i - 1].h - 1);
    }
  });

  it('emits sub links between non-root parents and children', () => {
    const root = branch('r', 'root', [
      branch('a', 'A', [leaf('a1', 'a1')])
    ]);
    const { links } = layout(root);
    const kinds = links.map((l) => l.kind).sort();
    expect(kinds).toEqual(['main', 'sub']);
  });

  it('honours explicit child direction', () => {
    const root = branch('r', 'root', [
      branch('a', 'A', [], SIDE_LEFT),
      branch('b', 'B', [], SIDE_RIGHT)
    ]);
    const { nodes } = layout(root);
    const a = nodes.find((n) => n.id === 'a');
    const b = nodes.find((n) => n.id === 'b');
    expect(a.direction).toBe(SIDE_LEFT);
    expect(b.direction).toBe(SIDE_RIGHT);
    // left side has negative x; right side positive x
    expect(a.x).toBeLessThan(0);
    expect(b.x).toBeGreaterThan(0);
  });

  it('renders a collapsed branch without expanding its children', () => {
    const root = branch('r', 'root', [
      branch('a', 'A', [leaf('a1', 'a1'), leaf('a2', 'a2')], undefined, 'pending')
    ]);
    root.children[0].expanded = false;
    const { nodes } = layout(root);
    expect(nodes.map((n) => n.id).sort()).toEqual(['a', 'r']);
    const a = nodes.find((n) => n.id === 'a');
    expect(a.collapsed).toBe(true);
    expect(a.hasChildren).toBe(true);
  });

  it('is deterministic — same input → same output nodes', () => {
    const make = () => branch('r', 'root', [
      branch('a', 'A', [leaf('a1', 'a1'), leaf('a2', 'a2')]),
      branch('b', 'B', [leaf('b1', 'b1')])
    ]);
    const out1 = layout(make());
    const out2 = layout(make());
    expect(JSON.stringify(out1.nodes)).toEqual(JSON.stringify(out2.nodes));
    expect(JSON.stringify(out1.links)).toEqual(JSON.stringify(out2.links));
  });

  it('DOWN direction stacks children below root', () => {
    const root = branch('r', 'root', [
      branch('a', 'A'),
      branch('b', 'B')
    ]);
    const { nodes } = layout(root, { direction: DIRECTION.DOWN });
    const r = nodes.find((n) => n.id === 'r');
    const a = nodes.find((n) => n.id === 'a');
    const b = nodes.find((n) => n.id === 'b');
    expect(a.direction).toBeUndefined();
    expect(b.direction).toBeUndefined();
    // Children appear below root: their y is greater than root's y.
    expect(a.y).toBeGreaterThan(r.y);
    expect(b.y).toBeGreaterThan(r.y);
  });
});

import { describe, it, expect } from 'vitest';
import {
  main,
  sub,
  rectFromNodes,
  directionClassFor,
  DIRECTION_CLASS
} from '../../src/modules/mindmap/services/ConnectorGeometry.js';

const baseRect = {
  pT: 0, pL: 0, pW: 180, pH: 44,
  cT: 100, cL: 260, cW: 180, cH: 44
};

describe('ConnectorGeometry', () => {
  describe('main()', () => {
    it('returns an SVG path d attribute starting with M', () => {
      const d = main(baseRect, { direction: DIRECTION_CLASS.RHS, containerHeight: 400 });
      expect(d.startsWith('M ')).toBe(true);
    });

    it('LHS main connector ends at the right edge of the child (cL + cW)', () => {
      const d = main(baseRect, { direction: DIRECTION_CLASS.LHS, containerHeight: 400 });
      // Path should terminate near (cL + cW, cT + cH/2) = (440, 122)
      expect(d).toContain('440');
      expect(d).toContain('122');
    });

    it('DOWN main connector uses the roundedVertical shape (V/Q/H commands)', () => {
      const d = main(baseRect, { direction: DIRECTION_CLASS.DOWN, containerHeight: 400 });
      expect(d).toMatch(/[VH]/);
      expect(d.startsWith('M ')).toBe(true);
    });

    it('returns vertical-only path when parent and child share x', () => {
      const d = main(
        { pT: 0, pL: 0, pW: 100, pH: 40, cT: 100, cL: 0, cW: 100, cH: 40 },
        { direction: DIRECTION_CLASS.DOWN, containerHeight: 400 }
      );
      expect(d).toBe('M 50 40 V 100');
    });
  });

  describe('sub()', () => {
    it('RHS sub connector uses cubic Bézier C command', () => {
      const d = sub(baseRect, { direction: DIRECTION_CLASS.RHS, isFirst: false });
      expect(d).toContain('C ');
    });

    it('LHS sub connector uses cubic Bézier with H end segment', () => {
      const d = sub(baseRect, { direction: DIRECTION_CLASS.LHS, isFirst: true });
      expect(d).toContain('C ');
      expect(d).toContain('H ');
    });

    it('honours custom nodeGapX (GAP value affects control points)', () => {
      const small = sub(baseRect, { direction: DIRECTION_CLASS.RHS, isFirst: false, nodeGapX: 10 });
      const large = sub(baseRect, { direction: DIRECTION_CLASS.RHS, isFirst: false, nodeGapX: 100 });
      expect(small).not.toEqual(large);
    });

    it('DOWN sub connector matches roundedVertical output', () => {
      const d = sub(baseRect, { direction: DIRECTION_CLASS.DOWN, isFirst: true });
      expect(d.startsWith('M ')).toBe(true);
      expect(d).toMatch(/V/);
    });
  });

  describe('helpers', () => {
    it('rectFromNodes maps {x,y,w,h} to {p*,c*}', () => {
      const parent = { x: 0, y: 0, w: 100, h: 40 };
      const child = { x: 200, y: 50, w: 100, h: 40 };
      const r = rectFromNodes(parent, child);
      expect(r).toEqual({ pT: 0, pL: 0, pW: 100, pH: 40, cT: 50, cL: 200, cW: 100, cH: 40 });
    });

    it('directionClassFor maps LayoutEngine link directions', () => {
      expect(directionClassFor({ direction: 0 })).toBe(DIRECTION_CLASS.RHS);
      expect(directionClassFor({ direction: 1 })).toBe(DIRECTION_CLASS.LHS);
      expect(directionClassFor({ direction: undefined })).toBe(DIRECTION_CLASS.DOWN);
    });
  });
});

