/**
 * @vitest-environment jsdom
 */
import { describe, it, expect, beforeEach } from 'vitest';
import { MindmapService } from '../../src/modules/mindmap/services/MindmapService.js';

function makeEventBus() {
  const subscribers = new Map();
  return {
    subscribe(name, fn) {
      if (!subscribers.has(name)) subscribers.set(name, []);
      subscribers.get(name).push(fn);
    },
    unsubscribe(name, fn) {
      const arr = subscribers.get(name);
      if (arr) subscribers.set(name, arr.filter((f) => f !== fn));
    },
    publish(name, payload) {
      const arr = subscribers.get(name);
      if (arr) for (const fn of arr) fn(payload);
    }
  };
}

describe('mindmap render helpers (jsdom)', () => {
  let svc;
  let container;

  beforeEach(async () => {
    const bus = makeEventBus();
    svc = new MindmapService(bus);
    svc.init({ storage: null });
    container = document.createElement('div');
    document.body.appendChild(container);
  });

  it('layout returns one node per NodeObj in the tree', async () => {
    const mapId = await svc.createMap('m');
    const root = svc._getMap(mapId).root;
    await svc.addBranch(root.id, 'b1');
    await svc.addBranch(root.id, 'b2');
    const { nodes, links } = svc.layout(mapId);
    expect(nodes.length).toBe(3); // root + 2 branches
    expect(links.length).toBe(2);
  });

  it('connectorPaths returns SVG d strings for every link', async () => {
    const mapId = await svc.createMap('m');
    const root = svc._getMap(mapId).root;
    await svc.addBranch(root.id, 'b1');
    const paths = svc.connectorPaths(mapId);
    expect(paths.length).toBe(1);
    expect(typeof paths[0].d).toBe('string');
    expect(paths[0].d.startsWith('M ')).toBe(true);
  });

  it('mounting components manually: branch-node element reflects data-status', async () => {
    // Simulates what ai-ui would do: create a DOM element with the right attributes.
    const mapId = await svc.createMap('m');
    const root = svc._getMap(mapId).root;
    const branch = await svc.addBranch(root.id, 'b1', { tag: 'phase' });
    await svc.updateStatus(branch.id, 'in_progress');

    const el = document.createElement('div');
    el.className = 'branch-node';
    el.dataset.status = branch.status;
    el.dataset.tag = branch.tag;
    el.dataset.nodeId = branch.id;
    container.appendChild(el);

    const rendered = container.querySelector(`[data-node-id="${branch.id}"]`);
    expect(rendered).toBeTruthy();
    expect(rendered.dataset.status).toBe('in_progress');
    expect(rendered.dataset.tag).toBe('phase');
  });

  it('after removeNode the layout no longer includes the removed id', async () => {
    const mapId = await svc.createMap('m');
    const root = svc._getMap(mapId).root;
    const branch = await svc.addBranch(root.id, 'b1');
    const before = svc.layout(mapId);
    expect(before.nodes.map((n) => n.id)).toContain(branch.id);
    await svc.removeNode(branch.id);
    const after = svc.layout(mapId);
    expect(after.nodes.map((n) => n.id)).not.toContain(branch.id);
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import { MindmapService } from '../../src/modules/mindmap/services/MindmapService.js';
import { HistoryService } from '../../src/modules/history/services/HistoryService.js';

/**
 * Use the REAL HistoryService so we exercise the actual undo/redo path
 * + the service's _onHistoryReversed subscription.
 */

function makeEventBus() {
  const subscribers = new Map();
  const published = [];
  return {
    published,
    subscribe(name, fn) {
      if (!subscribers.has(name)) subscribers.set(name, []);
      subscribers.get(name).push(fn);
    },
    unsubscribe(name, fn) {
      const arr = subscribers.get(name);
      if (arr) subscribers.set(name, arr.filter((f) => f !== fn));
    },
    publish(name, payload) {
      published.push({ name, payload });
      const arr = subscribers.get(name);
      if (arr) for (const fn of arr) fn(payload);
    }
  };
}

describe('mindmap undo/redo via real HistoryService', () => {
  let svc;
  let bus;
  let history;

  beforeEach(async () => {
    bus = makeEventBus();
    history = new HistoryService(bus);
    // Memory store (no IDB): pass no store, the HistoryStore falls back.
    await history.init({ store: { init: async () => {}, getAll: async () => [], put: async () => {}, clear: async () => {} } });
    svc = new MindmapService(bus);
    svc.init({ storage: null, history });
  });

  it('addBranch → undo removes the branch', async () => {
    const mapId = await svc.createMap('m');
    const root = svc._getMap(mapId).root;
    const branch = await svc.addBranch(root.id, 'b1');
    expect(svc.findNode(branch.id)).toBeTruthy();
    expect(svc.canUndo()).toBe(true);

    await svc.undo();
    expect(svc.findNode(branch.id)).toBeNull();
  });

  it('redo re-applies the undone addBranch', async () => {
    const mapId = await svc.createMap('m');
    const root = svc._getMap(mapId).root;
    const branch = await svc.addBranch(root.id, 'b1');
    await svc.undo();
    expect(svc.canRedo()).toBe(true);
    const result = await svc.redo();
    expect(result).toBeTruthy();
    expect(svc.findNode(branch.id)).toBeTruthy();
  });

  it('10-op sequence: undo to start, redo to end, tree matches', async () => {
    const mapId = await svc.createMap('m');
    const root = svc._getMap(mapId).root;
    const branches = [];
    for (let i = 0; i < 5; i += 1) {
      branches.push(await svc.addBranch(root.id, `b${i}`));
    }
    for (let i = 0; i < 5; i += 1) {
      await svc.updateStatus(branches[i].id, 'done');
    }
    const snapshot = JSON.stringify(svc._getMap(mapId).root);

    // Undo everything (10 ops + createMap may or may not count; loop until canUndo is false).
    let safety = 50;
    while (svc.canUndo() && safety > 0) { await svc.undo(); safety -= 1; }

    // Redo everything.
    safety = 50;
    while (svc.canRedo() && safety > 0) { await svc.redo(); safety -= 1; }

    expect(JSON.stringify(svc._getMap(mapId).root)).toEqual(snapshot);
  });

  it('updateStatus undo reverts to previous status', async () => {
    const mapId = await svc.createMap('m');
    const root = svc._getMap(mapId).root;
    const branch = await svc.addBranch(root.id, 'b');
    await svc.updateStatus(branch.id, 'done');
    expect(svc.findNode(branch.id).status).toBe('done');
    await svc.undo();
    expect(svc.findNode(branch.id).status).toBe('pending');
  });

  it('collapse undo restores previous expanded state', async () => {
    const mapId = await svc.createMap('m');
    const root = svc._getMap(mapId).root;
    const branch = await svc.addBranch(root.id, 'b');
    expect(branch.expanded).toBe(true);
    await svc.collapse(branch.id, true);
    expect(svc.findNode(branch.id).expanded).toBe(false);
    await svc.undo();
    expect(svc.findNode(branch.id).expanded).toBe(true);
  });

  it('removeNode undo restores the subtree', async () => {
    const mapId = await svc.createMap('m');
    const root = svc._getMap(mapId).root;
    const branch = await svc.addBranch(root.id, 'b');
    await svc.addLeaf(branch.id, 'l1');
    await svc.addLeaf(branch.id, 'l2');
    await svc.removeNode(branch.id);
    expect(svc.findNode(branch.id)).toBeNull();
    await svc.undo();
    const restored = svc.findNode(branch.id);
    expect(restored).toBeTruthy();
    expect(restored.children.length).toBe(2);
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import { MindmapService } from '../../src/modules/mindmap/services/MindmapService.js';

function makeEventBus() {
  const subscribers = new Map();
  return {
    subscribe(name, fn) {
      if (!subscribers.has(name)) subscribers.set(name, []);
      subscribers.get(name).push(fn);
    },
    unsubscribe() {},
    publish(name, payload) {
      const arr = subscribers.get(name);
      if (arr) for (const fn of arr) fn(payload);
    }
  };
}

describe('mindmap drag-drop validation (moveNode)', () => {
  let svc;
  let mapId;
  let root;
  let b1;
  let b2;
  let leaf;

  beforeEach(async () => {
    const bus = makeEventBus();
    svc = new MindmapService(bus);
    svc.init({ storage: null });
    mapId = await svc.createMap('m');
    root = svc._getMap(mapId).root;
    b1 = await svc.addBranch(root.id, 'b1');
    b2 = await svc.addBranch(root.id, 'b2');
    leaf = await svc.addLeaf(b1.id, 'l1');
  });

  it('moves a leaf between branches at end position', async () => {
    const moved = await svc.moveNode(leaf.id, b2.id);
    expect(moved.id).toBe(leaf.id);
    expect(svc.findNode(leaf.id)).toBeTruthy();
    // b2 now contains the leaf
    const b2fresh = svc.findNode(b2.id);
    expect(b2fresh.children.map((c) => c.id)).toContain(leaf.id);
    // b1 no longer contains it
    const b1fresh = svc.findNode(b1.id);
    expect(b1fresh.children.map((c) => c.id)).not.toContain(leaf.id);
  });

  it('moves a node to a specific index', async () => {
    const l2 = await svc.addLeaf(b2.id, 'l2');
    const l3 = await svc.addLeaf(b2.id, 'l3');
    // Move l3 to index 0 of b2
    await svc.moveNode(l3.id, b2.id, 0);
    const fresh = svc.findNode(b2.id);
    expect(fresh.children[0].id).toBe(l3.id);
    expect(fresh.children[1].id).toBe(l2.id);
  });

  it('rejects moving root', async () => {
    await expect(svc.moveNode(root.id, b1.id)).rejects.toThrowError(/root/);
  });

  it('rejects moving into a leaf', async () => {
    await expect(svc.moveNode(b1.id, leaf.id)).rejects.toThrowError(/leaf/);
  });

  it('rejects moving a node into its own descendant', async () => {
    // b1 has a leaf; trying to move b1 into that leaf should fail (also because leaf)
    // But the proper cycle check: move b1 into b2 when b2 is a child of b1.
    const subBranch = await svc.addBranch(b1.id, 'sub');
    // subBranch is now a child of b1. Try moving b1 into subBranch → cycle.
    await expect(svc.moveNode(b1.id, subBranch.id)).rejects.toThrowError(/cycle|descendant|itself/);
  });

  it('moveNode fires MINDMAP_NODE_MOVED with fromParent + toParent', async () => {
    const events = [];
    const bus = svc.eventBus;
    bus.subscribe('MINDMAP_NODE_MOVED', (p) => events.push(p));
    await svc.moveNode(leaf.id, b2.id);
    expect(events).toHaveLength(1);
    expect(events[0].fromParent).toBe(b1.id);
    expect(events[0].toParent).toBe(b2.id);
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import { MindmapService } from '../../src/modules/mindmap/services/MindmapService.js';
import { Search } from '../../src/modules/mindmap/services/Search.js';

function makeEventBus() {
  return { subscribe() {}, unsubscribe() {}, publish() {} };
}

function sampleTree() {
  return {
    id: 'root',
    topic: 'root',
    schemaType: 'mindmap/branch',
    status: 'pending',
    children: [
      {
        id: 'b1', topic: 'e2e-test', schemaType: 'mindmap/branch', status: 'in_progress', tag: 'phase',
        children: [
          { id: 'l1', topic: 'test /morphmap-review', schemaType: 'mindmap/leaf', status: 'pending', children: [] },
          { id: 'l2', topic: 'scout recon', schemaType: 'mindmap/leaf', status: 'done', children: [] },
          { id: 'l3', topic: 'research module patterns', schemaType: 'mindmap/leaf', status: 'blocked', children: [] }
        ]
      },
      {
        id: 'b2', topic: 'docs', schemaType: 'mindmap/branch', status: 'pending', tag: 'module',
        children: [
          { id: 'l4', topic: 'write readme', schemaType: 'mindmap/leaf', status: 'pending', children: [] }
        ]
      }
    ]
  };
}

describe('Search', () => {
  it('returns substring matches with high scores', () => {
    const s = new Search();
    const results = s.search(sampleTree(), 'test');
    expect(results.length).toBeGreaterThanOrEqual(2);
    // topic containing 'test' should be in results
    expect(results.some((r) => r.topic.includes('test'))).toBe(true);
  });

  it('returns empty array for no match', () => {
    const s = new Search();
    expect(s.search(sampleTree(), 'zzz-nope')).toEqual([]);
  });

  it('subsequence match still scores positive', () => {
    const s = new Search();
    const results = s.search(sampleTree(), 'rvmrph'); // subsequence of /morphmap-review
    // Subsequence matching is lenient; just ensure no crash and array shape.
    expect(Array.isArray(results)).toBe(true);
  });

  it('filter by status returns only matching nodes', () => {
    const s = new Search();
    const results = s.search(sampleTree(), '', { status: ['done'] });
    expect(results.length).toBeGreaterThanOrEqual(1);
    expect(results.every((r) => r.status === 'done')).toBe(true);
  });

  it('filter by tag scopes results', () => {
    const s = new Search();
    const results = s.search(sampleTree(), '', { tag: ['phase'] });
    expect(results.every((r) => r.tag === 'phase')).toBe(true);
    expect(results.some((r) => r.id === 'b1')).toBe(true);
  });

  it('results include path-from-root', () => {
    const s = new Search();
    const results = s.search(sampleTree(), 'recon');
    expect(results.length).toBe(1);
    const path = results[0].path;
    expect(path[0].id).toBe('root');
    expect(path[path.length - 1].id).toBe(results[0].nodeId);
  });
});

describe('MindmapService.search', () => {
  let svc;
  let mapId;

  beforeEach(async () => {
    const bus = makeEventBus();
    svc = new MindmapService(bus);
    svc.init({ storage: null });
    mapId = await svc.createMap('m');
    const root = svc._getMap(mapId).root;
    const b = await svc.addBranch(root.id, 'e2e-test', { tag: 'phase' });
